/* ===== UTILITÁRIOS ===== */
const $ = (s) => document.querySelector(s);
const money = (v) => v.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
const moneyTxt = (v) => money(v).replace(/\u00a0/g, " ");
const norm = (s) => s.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
const slug = (s) => norm(s).replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const icons = () => { if (window.lucide) lucide.createIcons(); };
const store = {
  get(k) { try { return JSON.parse(localStorage.getItem(k)); } catch (e) { return null; } },
  set(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) { /* ignora */ } }
};
// Cadeia de fallback das imagens: local → Unsplash → remove (aparece o logo "081" de fundo)
window.imgFallback = (el) => {
  if (el.dataset.fb) { const f = el.dataset.fb; el.removeAttribute("data-fb"); el.src = f; } else el.remove();
};
let toastTimer;
function toast(msg) {
  const t = $("#toast");
  t.textContent = msg; t.classList.add("show");
  clearTimeout(toastTimer); toastTimer = setTimeout(() => t.classList.remove("show"), 2600);
}

