const MENU = [];
let n = 0;
for (const cat in RAW) RAW[cat].forEach(([name, desc, price, img, file]) =>
  MENU.push({ id: ++n, cat, name, desc, price, img: img ? U(img) : "", local: PHOTOS[name] || file || `${IMG_DIR}${slug(name)}.jpg`, hay: norm(`${name} ${desc}`) }));
const byId = (id) => MENU.find((x) => x.id == id);
const imgTag = (m) => `<img src="${m.local}" data-fb="${m.img}" alt="${esc(m.name)}" loading="lazy" onerror="imgFallback(this)">`;

/* ===== PERSONALIZAÇÃO: ADICIONAIS, MOLHOS E OBSERVAÇÕES ===== */
// Categorias que abrem o modal de personalização ao clicar em "+ Adicionar".
// Bebidas e sobremesas vão direto para o carrinho.
const CUSTOM_CATS = ["cla", "aut", "aco"];
// [id, nome completo (modal), nome curto (carrinho e WhatsApp), preço]
const ADDONS = [
  { id: "burger", name: "Hambúrguer Extra 160g na Brasa", short: "Hambúrguer Extra 160g", price: 12 },
  { id: "bacon", name: "Bacon Artesanal Defumado Crocante", short: "Bacon Artesanal", price: 6 },
  { id: "cheddar", name: "Queijo Cheddar Inglês Extra", short: "Cheddar Inglês Extra", price: 5 },
  { id: "coalho", name: "Queijo Coalho Maçaricado", short: "Queijo Coalho Maçaricado", price: 6.5 },
  { id: "brie", name: "Queijo Brie Empanado", short: "Queijo Brie Empanado", price: 9 },
  { id: "cebola", name: "Cebola Caramelizada no Mel de Engenho", short: "Cebola Caramelizada", price: 4.5 }
];
const SAUCES = [
  { id: "maionese", name: "Maionese Verde da Casa", short: "Maionese Verde", price: 3 },
  { id: "aioli", name: "Aioli de Alho Assado", short: "Aioli de Alho Assado", price: 3.5 },
  { id: "bbq", name: "Molho Barbecue Defumado", short: "Molho Barbecue Defumado", price: 3 },
  { id: "sache", name: "Sachês de Ketchup & Mostarda", short: "Sachês de Ketchup & Mostarda", price: 0 }
];
const OPT = {}, OPT_ORDER = [];
[...ADDONS, ...SAUCES].forEach((o) => { OPT[o.id] = o; OPT_ORDER.push(o.id); });
// Texto simples para a mensagem do WhatsApp (sem quebras de linha nem símbolos de formatação)
const waText = (t) => String(t).replace(/[*_~`]/g, "").replace(/\s+/g, " ").trim();

/* ===== ESTADO ===== */
let activeCat = "all";
let query = "";
let sortBy = "featured";
let mode = "Retirada";                    // "Retirada" | "Delivery"
const cart = {};                          // { chave: { id, qty, extras: [ids], note } } — cada combinação de extras/obs é uma linha

// Uma linha do carrinho = item + extras + observação (mesma combinação soma a quantidade)
const lineKey = (id, extras, note) => [id, extras.join("+"), norm(note)].join("|");
const unitPrice = (l) => byId(l.id).price + l.extras.reduce((t, e) => t + OPT[e].price, 0);
function addLine(id, extras = [], note = "", qty = 1) {
  extras = OPT_ORDER.filter((e) => extras.includes(e));   // só ids válidos, sempre na mesma ordem
  note = String(note).replace(/\s+/g, " ").trim().slice(0, 200);
  const key = lineKey(id, extras, note);
  if (cart[key]) cart[key].qty += qty; else cart[key] = { id: Number(id), qty, extras, note };
}

/* ===== BUSCA + CATEGORIA + ORDENAÇÃO (combinados) ===== */
const SORTERS = {
  featured: (a, b) => a.id - b.id,
  price_asc: (a, b) => a.price - b.price || a.id - b.id,
  price_desc: (a, b) => b.price - a.price || a.id - b.id,
  az: (a, b) => a.name.localeCompare(b.name, "pt-BR"),
  za: (a, b) => b.name.localeCompare(a.name, "pt-BR")
};
function visibleItems() {
  const tokens = norm(query.trim()).split(/\s+/).filter(Boolean);
  return MENU
    .filter((m) => (activeCat === "all" || m.cat === activeCat) && tokens.every((t) => m.hay.includes(t)))
    .sort(SORTERS[sortBy]);
}
function renderFilters() {
  $("#filters").innerHTML = CATS.map(([k, label]) =>
    `<button class="${k === activeCat ? "active" : ""}" data-cat="${k}">${label}</button>`).join("");
}
function renderMenu() {
  const list = visibleItems();
  const q = query.trim();
  $("#resultsInfo").textContent = list.length
    ? `${list.length} ${list.length === 1 ? "item encontrado" : "itens encontrados"}${q ? ` para “${q}”` : ""}`
    : "";
  $("#clearSearch").hidden = !query;

  if (!list.length) {
    const canReset = q || activeCat !== "all" || sortBy !== "featured";
    const msg = q
      ? `Não encontramos “${esc(q)}”${activeCat !== "all" ? " nesta categoria" : ""}. Tente outro nome ou ingrediente.`
      : "Novidades doces em breve.";
    $("#menuGrid").innerHTML = `<div class="no-results"><i data-lucide="search-x"></i><h3>Nenhum item encontrado</h3><p>${msg}</p>${
      canReset ? `<button type="button" class="btn btn-sm" id="resetFilters">Limpar filtros</button>` : ""}</div>`;
    icons();
    return;
  }
  $("#menuGrid").innerHTML = list.map((m) => `
    <article class="card">
      <div class="thumb">${imgTag(m)}</div>
      <div class="card-body">
        <div class="card-top"><h3>${esc(m.name)}</h3><span class="price">${money(m.price)}</span></div>
        <p>${esc(m.desc)}</p>
        <button class="add" data-id="${m.id}">+ Adicionar</button>
      </div>
    </article>`).join("");
}

$("#filters").addEventListener("click", (e) => {
  const b = e.target.closest("button");
  if (!b) return;
  activeCat = b.dataset.cat;
  renderFilters(); renderMenu();
});
$("#searchInput").addEventListener("input", (e) => { query = e.target.value; renderMenu(); });
$("#searchInput").addEventListener("keydown", (e) => {
  if (e.key === "Escape" && query) { e.stopPropagation(); clearSearch(); }
});
$("#clearSearch").addEventListener("click", () => { clearSearch(); $("#searchInput").focus(); });
$("#sortSelect").addEventListener("change", (e) => { sortBy = e.target.value; renderMenu(); });
function clearSearch() { query = ""; $("#searchInput").value = ""; renderMenu(); }

$("#menuGrid").addEventListener("click", (e) => {
  if (e.target.closest("#resetFilters")) {
    activeCat = "all"; query = ""; sortBy = "featured";
    $("#searchInput").value = ""; $("#sortSelect").value = "featured";
    renderFilters(); renderMenu();
    return;
  }
  const b = e.target.closest(".add");
  if (!b) return;
  const m = byId(b.dataset.id);
  if (CUSTOM_CATS.includes(m.cat)) return openCustomize(m.id);   // lanches e porções: abre o modal
  addLine(m.id);                                                  // bebidas e sobremesas: direto no carrinho
  renderCart();
  b.textContent = "✓ Adicionado"; b.classList.add("added");
  setTimeout(() => { b.textContent = "+ Adicionar"; b.classList.remove("added"); }, 900);
});

/* ===== CARRINHO ===== */
function calc() {
  let sub = 0, count = 0;
  for (const k in cart) { sub += unitPrice(cart[k]) * cart[k].qty; count += cart[k].qty; }
  const fee = mode === "Delivery" && count > 0 ? DELIVERY_FEE : 0;
  return { sub, count, fee, total: sub + fee };
}
function renderTotals() {
  const { sub, count, fee, total } = calc();
  $("#sumSub").textContent = money(sub);
  $("#feeLabel").textContent = mode === "Delivery" ? `Taxa de Entrega (${money(DELIVERY_FEE)})` : "Taxa de Entrega";
  $("#sumFee").textContent = money(fee);
  $("#cartTotal").textContent = money(total);
  $("#cartCount").textContent = count;
  $("#tabCount").textContent = count;
  $("#tabCount").classList.toggle("on", count > 0);
}
function renderCart() {
  const keys = Object.keys(cart);
  $("#cartItems").innerHTML = keys.length ? keys.map((k) => {
    const l = cart[k], m = byId(l.id), unit = unitPrice(l), key = esc(k);
    const extras = l.extras.length ? `<span class="ci-extras">${l.extras.map((e) => `+ ${esc(OPT[e].short)}`).join(", ")}</span>` : "";
    const note = l.note ? `<span class="ci-note">Obs: ${esc(l.note)}</span>` : "";
    return `<div class="ci">
      <div class="ci-thumb">${imgTag(m)}</div>
      <div class="ci-info">
        <strong>${esc(m.name)}</strong>
        ${extras}${note}
        <small>${money(unit)} un.</small>
        <span class="ci-sub">${money(unit * l.qty)}</span>
      </div>
      <div class="ci-ctrl">
        <div class="qty"><button data-act="-" data-key="${key}" aria-label="Diminuir">−</button><span>${l.qty}</span><button data-act="+" data-key="${key}" aria-label="Aumentar">+</button></div>
        <button class="rm" data-act="rm" data-key="${key}" aria-label="Remover ${esc(m.name)}"><i data-lucide="trash-2"></i></button>
      </div>
    </div>`;
  }).join("") : `<div class="empty-cart"><i data-lucide="shopping-bag"></i><p>Seu pedido está vazio.</p><button type="button" class="btn btn-sm" id="goMenu">Ver cardápio</button></div>`;
  renderTotals();
  store.set("h081_cart2", cart);
  icons();
}
$("#cartItems").addEventListener("click", (e) => {
  if (e.target.closest("#goMenu")) { toggleCart(false); $("#menu").scrollIntoView({ behavior: "smooth" }); return; }
  const b = e.target.closest("button[data-act]");
  if (!b) return;
  const k = b.dataset.key, l = cart[k], act = b.dataset.act;
  if (!l) return;
  if (act === "rm") delete cart[k];
  else {
    l.qty += act === "+" ? 1 : -1;
    if (l.qty <= 0) delete cart[k];
  }
  renderCart();
});

/* ===== MODAL DE PERSONALIZAÇÃO DO LANCHE ===== */
const modal = $("#custModal");
let custId = null, lastFocus = null;
const optRow = (o) => `<label class="opt"><input type="checkbox" value="${o.id}"><span class="opt-box" aria-hidden="true"></span><span class="opt-name">${esc(o.name)}</span><span class="opt-price${o.price ? "" : " free"}">${o.price ? `+ ${money(o.price)}` : "Grátis"}</span></label>`;
$("#cmAddons").innerHTML = ADDONS.map(optRow).join("");
$("#cmSauces").innerHTML = SAUCES.map(optRow).join("");
const custExtras = () => [...modal.querySelectorAll("input[type=checkbox]:checked")].map((i) => i.value);
function updateCustTotal() {
  const m = byId(custId);
  if (!m) return;
  const total = m.price + custExtras().reduce((t, e) => t + OPT[e].price, 0);
  $("#cmAdd").textContent = `Adicionar ao Pedido — ${money(total)}`;   // recalcula em tempo real
}
function openCustomize(id) {
  const m = byId(id);
  if (!m) return;
  custId = m.id; lastFocus = document.activeElement;
  $("#cmThumb").innerHTML = imgTag(m);
  $("#cmName").textContent = m.name;
  $("#cmDesc").textContent = m.desc;
  $("#cmBase").textContent = money(m.price);
  modal.querySelectorAll("input[type=checkbox]").forEach((i) => { i.checked = false; });
  $("#cmNote").value = "";
  updateCustTotal();
  modal.hidden = false;
  document.body.classList.add("lock");
  $(".modal-scroll").scrollTop = 0;
  $("#custBox").focus();
  icons();
}
function closeCustomize() {
  if (modal.hidden) return;
  modal.hidden = true; custId = null;
  if (!$("#drawer").classList.contains("open")) document.body.classList.remove("lock");
  if (lastFocus && lastFocus.focus) lastFocus.focus();
}
modal.addEventListener("click", (e) => { if (e.target.closest("[data-close]")) closeCustomize(); });
modal.addEventListener("change", updateCustTotal);
$("#cmAdd").addEventListener("click", () => {
  const m = byId(custId);
  if (!m) return;
  addLine(m.id, custExtras(), $("#cmNote").value);
  renderCart();
  closeCustomize();
  toast(`${m.name} adicionado ao pedido`);
});
modal.addEventListener("keydown", (e) => { // mantém o foco do teclado dentro do modal
  if (e.key !== "Tab") return;
  const f = [...modal.querySelectorAll("button, input, textarea")].filter((x) => !x.disabled && x.offsetParent !== null);
  if (!f.length) return;
  const first = f[0], last = f[f.length - 1];
  if (e.shiftKey && (document.activeElement === first || document.activeElement === $("#custBox"))) { e.preventDefault(); last.focus(); }
  else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
});

/* ===== GAVETA: ABRIR/FECHAR E ABAS ===== */
function setTab(t) {
  document.querySelectorAll(".drawer-tabs button").forEach((b) => {
    const on = b.dataset.tab === t;
    b.classList.toggle("active", on); b.setAttribute("aria-selected", on);
  });
  $("#panelOrder").classList.toggle("active", t === "order");
  $("#panelDelivery").classList.toggle("active", t === "delivery");
}
function toggleCart(open, tab) {
  if (open && tab) setTab(tab);
  $("#drawer").classList.toggle("open", open);
  $("#overlay").classList.toggle("open", open);
  document.body.classList.toggle("lock", open || !$("#custModal").hidden);
}
$("#openCart").addEventListener("click", () => toggleCart(true, "order"));
$("#closeCart").addEventListener("click", () => toggleCart(false));
$("#overlay").addEventListener("click", () => toggleCart(false));
document.addEventListener("keydown", (e) => {
  if (e.key !== "Escape") return;
  if (!modal.hidden) closeCustomize(); else toggleCart(false);
});
document.querySelectorAll(".drawer-tabs button").forEach((b) => b.addEventListener("click", () => setTab(b.dataset.tab)));
// Link "Entrega" do menu abre a gaveta direto na aba de entrega
$("#navDelivery").addEventListener("click", (e) => { e.preventDefault(); toggleCart(true, "delivery"); });

/* ===== ENTREGA: MODO, CEP E TAXA FIXA ===== */
let lookup = ""; // texto do último local consultado (bairro/cidade)
function updateDeliveryBox() {
  const box = $("#deliveryResult");
  if (mode === "Delivery") {
    box.className = "d-result";
    box.innerHTML = `<i data-lucide="circle-check"></i><div>
      <strong>Entrega Disponível — Taxa Fixa: ${money(DELIVERY_FEE)}</strong>
      <span>(Tempo estimado: ${DELIVERY_ETA})</span>${lookup ? `<span class="d-where">${esc(lookup)}</span>` : ""}</div>`;
  } else {
    box.className = "d-result pickup";
    box.innerHTML = `<i data-lucide="store"></i><div>
      <strong>Retirada no Balcão — sem taxa de entrega</strong>
      <span>${STORE_ADDRESS}</span></div>`;
  }
  icons();
}
function setMode(m) {
  mode = m;
  document.querySelector(`input[name=mode][value="${m}"]`).checked = true;
  $("#addrWrap").hidden = m !== "Delivery";
  $("#paySelect").options[1].text = m === "Delivery" ? "Cartão na entrega" : "Cartão na retirada";
  updateDeliveryBox();
  renderTotals();
}
document.querySelectorAll("input[name=mode]").forEach((r) => r.addEventListener("change", () => setMode(r.value)));

// Máscara de CEP (só quando o campo contém apenas números)
$("#cepInput").addEventListener("input", (e) => {
  const v = e.target.value;
  e.target.classList.remove("invalid");
  if (/^[\d-]*$/.test(v)) {
    const d = v.replace(/\D/g, "").slice(0, 8);
    e.target.value = d.length > 5 ? `${d.slice(0, 5)}-${d.slice(5)}` : d;
  }
});
$("#cepInput").addEventListener("keydown", (e) => { if (e.key === "Enter") { e.preventDefault(); consultDelivery(); } });
$("#cepBtn").addEventListener("click", consultDelivery);

async function consultDelivery() {
  const input = $("#cepInput"), raw = input.value.trim();
  const digits = raw.replace(/\D/g, ""), onlyNum = /^[\d\s.-]+$/.test(raw);
  if (!raw) { input.classList.add("invalid"); input.focus(); return toast("Digite seu CEP ou bairro para consultar."); }
  if (onlyNum && digits.length !== 8) { input.classList.add("invalid"); input.focus(); return toast("CEP incompleto. Digite os 8 dígitos ou o nome do bairro."); }
  input.classList.remove("invalid");
  lookup = onlyNum ? `CEP ${digits.slice(0, 5)}-${digits.slice(5)}` : raw;
  setMode("Delivery"); // consultar entrega ativa o Delivery e soma a taxa
  if (onlyNum) { // tenta completar o endereço pelo ViaCEP (opcional: se falhar, a entrega segue disponível)
    try {
      const d = await (await fetch(`https://viacep.com.br/ws/${digits}/json/`)).json();
      if (!d.erro) {
        lookup = `${[d.bairro, d.localidade].filter(Boolean).join(", ")} · CEP ${digits.slice(0, 5)}-${digits.slice(5)}`;
        const addr = $("#custAddr");
        if (!addr.value.trim()) addr.value = [d.logradouro, d.bairro, `${d.localidade} - ${d.uf}`].filter(Boolean).join(", ");
        updateDeliveryBox();
      }
    } catch (err) { /* sem internet ou ViaCEP fora: ignora */ }
  }
}

/* ===== PAGAMENTO ===== */
$("#paySelect").addEventListener("change", (e) => { $("#changeWrap").hidden = e.target.value !== "Dinheiro"; });
["#custName", "#custAddr"].forEach((s) => $(s).addEventListener("input", (e) => e.target.classList.remove("invalid")));

/* ===== ENVIO PARA O WHATSAPP ===== */
function invalid(sel, msg) {
  setTab("delivery");
  const el = $(sel); el.classList.add("invalid"); el.focus();
  toast(msg);
}
$("#checkout").addEventListener("click", () => {
  const ids = Object.keys(cart);
  if (!ids.length) { setTab("order"); return toast("Adicione itens ao pedido primeiro."); }
  const name = $("#custName").value.trim(), addr = $("#custAddr").value.trim();
  if (!name) return invalid("#custName", "Informe seu nome.");
  if (mode === "Delivery" && !addr) return invalid("#custAddr", "Informe o endereço de entrega.");

  const { total } = calc();
  const blocks = ids.map((k) => {
    const l = cart[k], m = byId(l.id);
    const out = [`${l.qty}x ${m.name} (${moneyTxt(m.price)})`];
    l.extras.forEach((e) => out.push(`   + ${OPT[e].short} (${OPT[e].price > 0 ? `+ ${moneyTxt(OPT[e].price)}` : "Grátis"})`));
    if (l.note) out.push(`   _Obs: ${waText(l.note)}_`);
    if (l.qty > 1 || l.extras.length) out.push(`   Subtotal do item: ${moneyTxt(unitPrice(l) * l.qty)}`);
    return out.join("\n");
  });
  const general = waText($("#orderNote").value);

  let pay = $("#paySelect").value;
  if (pay === "Cartão") pay = mode === "Delivery" ? "Cartão na entrega" : "Cartão na retirada";
  if (pay === "Dinheiro") {
    const raw = $("#changeFor").value.trim(), num = parseFloat(raw.replace(/\./g, "").replace(",", "."));
    if (raw) pay += ` (troco para ${isFinite(num) && num > 0 ? moneyTxt(num) : raw})`;
  }
  const cepRaw = $("#cepInput").value.trim();
  const ref = cepRaw ? ` (${/^[\d\s.-]+$/.test(cepRaw) ? "CEP" : "Ref."} ${cepRaw})` : "";

  const msg = [
    "*NOVO PEDIDO — HAMBURGUERIA 081*", "",
    "*Itens do Pedido:*",
    blocks.join("\n\n"), "",
    `*Cliente:* ${name}`,
    mode === "Delivery" ? `*Entrega:* Delivery (Taxa Fixa: ${moneyTxt(DELIVERY_FEE)})` : "*Entrega:* Retirada no Balcão (sem taxa)",
    ...(mode === "Delivery" ? [`*Endereço:* ${addr}${ref}`] : []),
    `*Pagamento:* ${pay}`,
    ...(general ? [`*Obs. Geral:* ${general}`] : []), "",
    `*TOTAL FINAL: ${moneyTxt(total)}*`
  ].join("\n");

  const url = `https://wa.me/${WHATSAPP}?text=${encodeURIComponent(msg)}`;
  if (!window.open(url, "_blank")) location.href = url; // fallback se o navegador bloquear a nova aba
});

/* ===== HEADER E MENU MOBILE ===== */
window.addEventListener("scroll", () => $("#header").classList.toggle("scrolled", scrollY > 40));
$("#burger").addEventListener("click", () => $("#nav").classList.toggle("open"));
$("#nav").addEventListener("click", () => $("#nav").classList.remove("open"));
$("#reserveLink").href = `https://wa.me/${WHATSAPP}?text=${encodeURIComponent("Olá! Gostaria de fazer uma reserva na Hamburgueria 081.")}`;
$("#waLink").href = $("#footWa").href = `https://wa.me/${WHATSAPP}?text=${encodeURIComponent("Olá! Gostaria de fazer um pedido na Hamburgueria 081.")}`;

/* ===== INÍCIO ===== */
(() => { // recupera o carrinho salvo no navegador
  const saved = store.get("h081_cart2");
  if (saved && typeof saved === "object") for (const k in saved) {
    const l = saved[k];
    if (!l || !byId(l.id) || !(l.qty > 0)) continue;
    addLine(l.id, Array.isArray(l.extras) ? l.extras : [], typeof l.note === "string" ? l.note : "", Math.min(Math.floor(l.qty), 99));
  }
  const old = !saved && store.get("h081_cart");   // formato antigo: { idDoItem: quantidade }
  if (old && typeof old === "object") for (const id in old) if (byId(id) && old[id] > 0) addLine(id, [], "", Math.min(Math.floor(old[id]), 99));
})();
renderFilters(); renderMenu(); renderCart(); setMode("Retirada");
icons();

/* ===== HERO ANIMADO ===== */
(() => {
  const hero = $("#inicio"), stage = $("#stage"), tilt = $("#tilt"), cv = $("#embers");
  if (!hero || !cv || matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  let tx = 0, ty = 0, cx = 0, cy = 0, visible = true;
  const lim = (v) => Math.max(-1, Math.min(1, v));

  // Parallax 3D: mouse/toque e giroscópio
  hero.addEventListener("pointermove", (e) => {
    const r = hero.getBoundingClientRect();
    tx = lim(((e.clientX - r.left) / r.width) * 2 - 1); ty = lim(((e.clientY - r.top) / r.height) * 2 - 1);
  });
  hero.addEventListener("pointerleave", () => { tx = 0; ty = 0; });
  addEventListener("deviceorientation", (e) => {
    if (e.gamma == null) return;
    tx = lim(e.gamma / 30); ty = lim((e.beta - 45) / 30);
  });

  // Canvas de brasas
  const ctx = cv.getContext("2d");
  let W = 0, H = 0;
  const size = () => {
    const d = Math.min(devicePixelRatio || 1, 1.5);
    W = stage.clientWidth; H = stage.clientHeight;
    cv.width = W * d; cv.height = H * d; ctx.setTransform(d, 0, 0, d, 0, 0);
  };
  new ResizeObserver(size).observe(stage); size();

  // Sprites pré-renderizados (rápido no celular)
  const mk = (c) => {
    const s = document.createElement("canvas"); s.width = s.height = 32;
    const x = s.getContext("2d"), g = x.createRadialGradient(16, 16, 0, 16, 16, 16);
    g.addColorStop(0, "#fff"); g.addColorStop(.22, c); g.addColorStop(1, "rgba(255,85,0,0)");
    x.fillStyle = g; x.fillRect(0, 0, 32, 32); return s;
  };
  const SP = [mk("#FF5500"), mk("#D4AF37")];
  const spawn = (p, init) => {
    const fire = Math.random() < .7; // 70% saem da lareira, 30% flutuam perto do burger
    p.x = W * (fire ? .76 + Math.random() * .18 : .3 + Math.random() * .42);
    p.y = H * (fire ? .6 - Math.random() * .06 : .35 + Math.random() * .5);
    p.vy = -(fire ? 30 + Math.random() * 70 : 8 + Math.random() * 22) * H / 800;
    p.sw = 8 + Math.random() * 16; p.ph = Math.random() * 6.28;
    p.r = (1.4 + Math.random() * 3.2) * W / 1400;
    p.max = fire ? 3 + Math.random() * 3.5 : 4 + Math.random() * 4;
    p.life = init ? Math.random() * p.max : 0;
    p.s = SP[Math.random() < .65 ? 0 : 1];
    return p;
  };
  const N = matchMedia("(max-width: 820px)").matches ? 35 : 70;
  const P = Array.from({ length: N }, () => spawn({}, true));

  new IntersectionObserver(([e]) => (visible = e.isIntersecting)).observe(hero);
  let last = performance.now(), t = 0;
  const frame = (now) => {
    requestAnimationFrame(frame);
    if (!visible || document.hidden) { last = now; return; } // pausa fora da tela
    const dt = Math.min((now - last) / 1000, .05); last = now; t += dt;
    cx += (tx - cx) * .06; cy += (ty - cy) * .06;
    tilt.style.setProperty("--rx", (-cy * 9).toFixed(2) + "deg");
    tilt.style.setProperty("--ry", (cx * 13).toFixed(2) + "deg");
    stage.style.setProperty("--bx", (cx * -10).toFixed(1) + "px");
    stage.style.setProperty("--by", (cy * -6).toFixed(1) + "px");
    ctx.clearRect(0, 0, W, H);
    ctx.globalCompositeOperation = "lighter";
    for (const p of P) {
      p.life += dt;
      if (p.life > p.max) spawn(p);
      p.y += p.vy * dt * (1 - (p.life / p.max) * .4);
      p.x += (Math.sin(t * .9 + p.ph) * p.sw + 12 * W / 1400) * dt; // vento
      const a = Math.sin(Math.PI * p.life / p.max) * (.65 + .35 * Math.sin(t * 10 + p.ph)); // brilho pulsante
      const s = p.r * 7;
      ctx.globalAlpha = Math.max(a, 0);
      ctx.drawImage(p.s, p.x - s / 2, p.y - s / 2, s, s);
    }
    ctx.globalAlpha = 1;
  };
  requestAnimationFrame(frame);
})();